    opacity: 1;
}
.elementor-control-type-asenha_switcher .elementor-switch-handle {
    position: absolute;
    top: 1px;
    left: 1px;
    width: 18px;
    height: 18px;
    background: white;
    border-radius: 10px;
    transition: left 0.15s ease-out;
}
